'use client';

import { useEffect, useState } from 'react';
import Layout from '@/components/layout/layout';
import AuthGuard from '@/components/auth/auth-guard';
import { formatCurrency } from '@/lib/utils';
import { 
  ShoppingCartIcon, 
  MagnifyingGlassIcon, 
  TrashIcon, 
  CheckIcon,
  BuildingOfficeIcon,
  CreditCardIcon,
  BanknotesIcon,
  DevicePhoneMobileIcon
} from '@heroicons/react/24/outline';
import apiClient, { endpoints } from '@/lib/api';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { useToast } from '@/components/ui/toaster';
import { CubeIcon } from '@heroicons/react/24/outline';

// Types
interface Product {
  id: string;
  name: string;
  sku: string;
  price: number;
  currentStock?: number;
  category: string;
}

interface CartItem extends Product {
  quantity: number;
}

interface Branch {
  id: string;
  name: string;
  code: string;
}

export default function POSPage() {
  const { toast } = useToast();
  const [searchTerm, setSearchTerm] = useState('');
  const [categories, setCategories] = useState<string[]>(['All']);
  const [selectedCategory, setSelectedCategory] = useState('All');
  const [products, setProducts] = useState<Product[]>([]);
  const [branches, setBranches] = useState<Branch[]>([]);
  const [selectedBranch, setSelectedBranch] = useState<string>('');
  const [paymentMethod, setPaymentMethod] = useState<'cash' | 'card' | 'transfer'>('cash');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [checkingOut, setCheckingOut] = useState(false);

  useEffect(() => {
    const fetchData = async () => {
      try {
        setLoading(true);
        const [productsRes, branchesRes] = await Promise.all([
          apiClient.get(endpoints.products),
          apiClient.get(endpoints.branches)
        ]);
        
        const prods = productsRes.data || [];
        setProducts(prods);

        const brs = branchesRes.data || [];
        setBranches(brs);
        if (brs.length > 0) setSelectedBranch(brs[0].id);

        // Extract unique categories
        const cats = ['All', ...new Set(prods.map((p: Product) => p.category)) as Set<string>];
        setCategories(cats);
        setLoading(false);
      } catch (err) {
        console.error('POS fetch error:', err);
        setLoading(false);
      }
    };
    fetchData();
  }, []);

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) {
        return prev.map(item =>
          item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item
        );
      }
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const updateQuantity = (id: string, delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.id === id) {
        const newQty = Math.max(1, item.quantity + delta);
        return { ...item, quantity: newQty };
      }
      return item;
    }));
  };

  const removeFromCart = (id: string) => {
    setCart(prev => prev.filter(item => item.id !== id));
  };

  const total = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);

  const handleCheckout = async () => {
    if (cart.length === 0) return;
    if (!selectedBranch) {
      toast({
        title: "Branch Required",
        description: "Please select a branch before checkout.",
        variant: "destructive",
      });
      return;
    }

    try {
      setCheckingOut(true);
      const saleData = {
        branch_id: selectedBranch,
        items: cart.map(item => ({
          product_id: item.id,
          quantity: item.quantity,
          price: item.price
        })),
        total_amount: total,
        payment_method: paymentMethod
      };

      await apiClient.post(endpoints.sales, saleData);

      toast({
        title: "Sale Successful",
        description: `Sale of ${formatCurrency(total)} recorded at ${branches.find(b => b.id === selectedBranch)?.name}.`,
      });

      setCart([]);
      setCheckingOut(false);
    } catch (err) {
      console.error('Checkout error:', err);
      toast({
        variant: "destructive",
        title: "Checkout Failed",
        description: "An error occurred while processing the sale.",
      });
      setCheckingOut(false);
    }
  };

  const filteredProducts = products.filter(product => {
    const matchesSearch = product.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      product.sku.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCategory = selectedCategory === 'All' || product.category === selectedCategory;
    return matchesSearch && matchesCategory;
  });

  return (
    <AuthGuard>
      <Layout>
        <div className="space-y-6">
          {/* POS Header */}
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
            <div>
              <h1 className="text-2xl font-bold text-primary">Point of Sale</h1>
              <p className="text-sm text-text-secondary">Process sales and manage inventory</p>
            </div>
            
            <div className="flex flex-wrap items-center gap-4">
              {/* Branch Selector */}
              <div className="flex items-center space-x-2 bg-surface p-2 px-4 rounded-xl border border-divider">
                <BuildingOfficeIcon className="h-5 w-5 text-text-secondary" />
                <select 
                  value={selectedBranch}
                  onChange={(e) => setSelectedBranch(e.target.value)}
                  className="bg-transparent border-none text-sm font-bold text-primary focus:ring-0 cursor-pointer"
                >
                  <option value="" disabled>Select Branch</option>
                  {branches.map(branch => (
                    <option key={branch.id} value={branch.id}>{branch.name}</option>
                  ))}
                </select>
              </div>

              <div className="flex items-center space-x-6 bg-surface p-4 rounded-xl border border-divider">
                <div className="text-right">
                  <p className="text-xs text-text-secondary uppercase font-bold tracking-wider">Total Amount</p>
                  <p className="text-2xl font-black text-primary">{formatCurrency(total)}</p>
                </div>
                <div className="relative">
                  <div className="h-12 w-12 bg-primary/10 rounded-full flex items-center justify-center">
                    <ShoppingCartIcon className="h-6 w-6 text-primary" />
                  </div>
                  {cart.length > 0 && (
                    <span className="absolute -top-1 -right-1 h-5 w-5 bg-error text-white text-[10px] font-bold rounded-full flex items-center justify-center border-2 border-surface">
                      {cart.length}
                    </span>
                  )}
                </div>
              </div>
            </div>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
            {/* Products Section */}
            <div className="lg:col-span-8 space-y-6">
              <div className="flex flex-col sm:flex-row gap-4">
                <div className="relative flex-1">
                  <MagnifyingGlassIcon className="absolute left-3 top-1/2 -translate-y-1/2 h-5 w-5 text-text-secondary" />
                  <Input
                    placeholder="Search Products..."
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="pl-10 h-12 text-base"
                  />
                </div>
                <div className="flex gap-2 overflow-x-auto pb-2 sm:pb-0 no-scrollbar">
                  {categories.map(category => (
                    <Button
                      key={category}
                      variant={selectedCategory === category ? 'default' : 'secondary'}
                      onClick={() => setSelectedCategory(category)}
                      className="whitespace-nowrap rounded-full px-6"
                    >
                      {category}
                    </Button>
                  ))}
                </div>
              </div>

              {loading ? (
                <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                  {[...Array(6)].map((_, i) => (
                    <div key={i} className="card p-4 h-48 animate-pulse bg-surface/50"></div>
                  ))}
                </div>
              ) : (
                <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4">
                  {filteredProducts.map(product => (
                    <div
                      key={product.id}
                      className="card p-4 hover-lift cursor-pointer flex flex-col justify-between group"
                      onClick={() => addToCart(product)}
                    >
                      <div>
                        <div className="h-20 bg-surface rounded-lg flex items-center justify-center mb-3 group-hover:bg-primary/5 transition-colors">
                          <CubeIcon className="h-10 w-10 text-text-secondary group-hover:text-primary/40" />
                        </div>
                        <h3 className="font-bold text-primary text-sm line-clamp-1">{product.name}</h3>
                        <p className="text-[10px] uppercase font-bold text-text-secondary">{product.category}</p>
                      </div>
                      <div className="mt-4 flex flex-col gap-3">
                        <p className="text-lg font-black text-primary">{formatCurrency(product.price)}</p>
                        <Button size="sm" className="w-full text-xs font-bold rounded-lg py-0 h-8 opacity-0 group-hover:opacity-100 transition-opacity">
                          Add to Cart
                        </Button>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>

            {/* Cart Section */}
            <div className="lg:col-span-4">
              <div className="card h-full flex flex-col p-6 sticky top-24">
                <h2 className="text-xl font-bold text-primary mb-6 flex items-center gap-2">
                  Cart Items
                </h2>

                <div className="flex-1 overflow-y-auto space-y-4 pr-1 min-h-[300px]">
                  {cart.length === 0 ? (
                    <div className="h-full flex flex-col items-center justify-center text-text-secondary opacity-30 italic py-12">
                      <ShoppingCartIcon className="h-16 w-16 mb-4" />
                      <p>Your cart is empty</p>
                    </div>
                  ) : (
                    cart.map((item) => (
                      <div key={item.id} className="flex items-center gap-4 p-3 rounded-xl bg-surface border border-divider group">
                        <div className="flex-1">
                          <p className="text-sm font-bold text-primary line-clamp-1">{item.name}</p>
                          <p className="text-xs font-bold text-text-secondary">{formatCurrency(item.price)}</p>
                        </div>
                        <div className="flex items-center gap-3">
                          <div className="flex items-center bg-background rounded-lg border border-divider">
                            <button
                              onClick={(e) => { e.stopPropagation(); updateQuantity(item.id, -1); }}
                              className="w-8 h-8 flex items-center justify-center text-primary font-bold hover:bg-surface rounded-l-lg"
                            > - </button>
                            <span className="w-8 text-center text-sm font-bold">{item.quantity}</span>
                            <button
                              onClick={(e) => { e.stopPropagation(); updateQuantity(item.id, 1); }}
                              className="w-8 h-8 flex items-center justify-center text-primary font-bold hover:bg-surface rounded-r-lg"
                            > + </button>
                          </div>
                          <button
                            onClick={(e) => { e.stopPropagation(); removeFromCart(item.id); }}
                            className="p-2 text-error hover:bg-error/10 rounded-lg transition-colors"
                          >
                            <TrashIcon className="h-4 w-4" />
                          </button>
                        </div>
                      </div>
                    ))
                  )}
                </div>

                <div className="mt-6 pt-6 border-t border-divider space-y-4">
                  {/* Payment Method Selector */}
                  <div className="space-y-3">
                    <p className="text-xs font-bold text-text-secondary uppercase tracking-widest px-1">Payment Method</p>
                    <div className="grid grid-cols-3 gap-2">
                      <button
                        onClick={() => setPaymentMethod('cash')}
                        className={`flex flex-col items-center justify-center p-3 rounded-xl border-2 transition-all ${
                          paymentMethod === 'cash' 
                            ? 'border-primary bg-primary/5 text-primary' 
                            : 'border-divider hover:border-text-secondary/30 text-text-secondary'
                        }`}
                      >
                        <BanknotesIcon className="h-5 w-5 mb-1" />
                        <span className="text-[10px] font-bold">Cash</span>
                      </button>
                      <button
                        onClick={() => setPaymentMethod('card')}
                        className={`flex flex-col items-center justify-center p-3 rounded-xl border-2 transition-all ${
                          paymentMethod === 'card' 
                            ? 'border-primary bg-primary/5 text-primary' 
                            : 'border-divider hover:border-text-secondary/30 text-text-secondary'
                        }`}
                      >
                        <CreditCardIcon className="h-5 w-5 mb-1" />
                        <span className="text-[10px] font-bold">Card</span>
                      </button>
                      <button
                        onClick={() => setPaymentMethod('transfer')}
                        className={`flex flex-col items-center justify-center p-3 rounded-xl border-2 transition-all ${
                          paymentMethod === 'transfer' 
                            ? 'border-primary bg-primary/5 text-primary' 
                            : 'border-divider hover:border-text-secondary/30 text-text-secondary'
                        }`}
                      >
                        <DevicePhoneMobileIcon className="h-5 w-5 mb-1" />
                        <span className="text-[10px] font-bold">Transfer</span>
                      </button>
                    </div>
                  </div>

                  <div className="flex justify-between items-center px-1 pt-2">
                    <span className="text-sm font-bold text-text-secondary">Total Balance:</span>
                    <span className="text-2xl font-black text-primary">{formatCurrency(total)}</span>
                  </div>
                  <Button
                    className="w-full h-14 text-lg font-black rounded-xl gap-3 shadow-lg shadow-primary/20"
                    disabled={cart.length === 0 || checkingOut}
                    onClick={handleCheckout}
                  >
                    {checkingOut ? (
                      <span className="animate-spin rounded-full h-5 w-5 border-b-2 border-white"></span>
                    ) : (
                      <>
                        <CheckIcon className="h-6 w-6" />
                        Checkout
                      </>
                    )}
                  </Button>
                </div>
              </div>
            </div>
          </div>
        </div>
      </Layout>
    </AuthGuard>
  );
}
